mapper.select:
SELECT il.id, il.drug_id, il.hospital_id, il.type, il.quantity, il.batch_no,
       il.operator, il.remark, il.created_at,
       d.name AS drug_name, h.name AS hospital_name
FROM inventory_log il
LEFT JOIN drug_info d ON il.drug_id = d.id
LEFT JOIN hospital h ON il.hospital_id = h.id

    AND il.drug_id = #{drugId}
    AND il.hospital_id = #{hospitalId}
    AND il.type = #{type}

ORDER BY il.created_at DESC
